package com.harish.student_management.service; import com.harish.student_management.dto.CertificateDtos.*; import com.harish.student_management.entity.*; import com.harish.student_management.exception.ResourceNotFoundException; import com.harish.student_management.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class CertificateServiceImpl implements CertificateService {private final CertificateTemplateRepository templates;private final CertificateRepository certificates;private final StudentRepository students; public Object template(TemplateRequest r){Set<String> t=Set.of("BONAFIDE","STUDY","CHARACTER","TRANSFER","ACHIEVEMENT");String type=r.getCertificateType().toUpperCase();if(!t.contains(type))throw new IllegalArgumentException("Unsupported certificate type");return templates.save(CertificateTemplate.builder().certificateType(type).template(r.getTemplate()).build());} public Response generate(GenerateRequest r){Student s=students.findById(r.getStudentId()).orElseThrow(()->new ResourceNotFoundException("Student not found"));String type=r.getCertificateType().toUpperCase();CertificateTemplate t=templates.findByCertificateType(type).orElseThrow(()->new ResourceNotFoundException("Certificate template not configured"));String no="CERT-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();String c=t.getTemplate().replace("${studentName}",s.getName()).replace("${className}",s.getSection()==null?"":s.getSection().getClassEntity().getName()).replace("${sectionName}",s.getSection()==null?"":s.getSection().getName()).replace("${certificateNumber}",no).replace("${issueDate}",LocalDate.now().toString());return map(certificates.save(Certificate.builder().student(s).certificateType(type).certificateNumber(no).content(c).issueDate(LocalDate.now()).build()));} @Transactional(readOnly=true) public List<Response> student(Long id){return certificates.findByStudentIdOrderByIssueDateDesc(id).stream().map(this::map).toList();}@Transactional(readOnly=true) public byte[] download(Long id){return certificates.findById(id).map(c->c.getContent().getBytes(StandardCharsets.UTF_8)).orElseThrow(()->new ResourceNotFoundException("Certificate not found"));}private Response map(Certificate c){return Response.builder().id(c.getId()).studentId(c.getStudent().getId()).studentName(c.getStudent().getName()).certificateType(c.getCertificateType()).certificateNumber(c.getCertificateNumber()).content(c.getContent()).issueDate(c.getIssueDate()).build();}}
